"""Separater Direktimport vollstaendiger IVW-Details fuer SQLMesh."""

from __future__ import annotations

import argparse
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal

import mariadb
import pandas as pd

from ..constants import DATABASE
from .client import DbCredentials, connect_to_db

ReportArt = Literal["Print", "ePaper"]
TARGET_TABLE = "tb_ivw_fulfillment_detail"
STAGING_TABLE = "tmp_ivw_fulfillment_import"

CREATE_TARGET_SQL = """
CREATE TABLE IF NOT EXISTS `{table}` (
    `schedule` CHAR(7) NULL,
    `subscriptionid` BIGINT UNSIGNED NOT NULL,
    `orderid` BIGINT UNSIGNED NOT NULL,
    `total_paid` DECIMAL(18, 4) NULL,
    `product_base_price` DECIMAL(18, 4) NULL,
    `contract_length_type_name` VARCHAR(20) NULL,
    `contract_length` DECIMAL(18, 4) NULL,
    `fulfilment_count` DECIMAL(18, 4) NOT NULL,
    `report_ivwcategory` VARCHAR(20) NULL,
    `ivwcategory_cf` VARCHAR(20) NULL,
    `ivwcategory_berechnet` VARCHAR(20) NULL,
    `art` ENUM('Print', 'ePaper') NOT NULL,
    `lieferdatum` DATE NOT NULL,
    `ausgabedatum` DATE NULL,
    `pva` VARCHAR(20) NULL,
    `gesamt_pva` VARCHAR(20) NULL,
    `objekt` VARCHAR(20) NULL,
    `welt` VARCHAR(10) NULL,
    `ivwcategory` VARCHAR(30) NULL,
    `meldung` VARCHAR(30) NULL,
    `is_ivw_relevant` TINYINT(1) NOT NULL DEFAULT 0,
    `plz` VARCHAR(10) NULL,
    PRIMARY KEY (`subscriptionid`, `lieferdatum`, `art`),
    INDEX `idx_orderid` (`orderid`),
    INDEX `idx_lieferdatum` (`lieferdatum`),
    INDEX `idx_sqlmesh_dimensions` (`lieferdatum`, `art`, `pva`, `welt`, `ivwcategory`, `meldung`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
"""

CREATE_STAGING_SQL = """
CREATE TEMPORARY TABLE `{table}` (
    `schedule` CHAR(7) NULL,
    `subscriptionid` BIGINT UNSIGNED NOT NULL,
    `orderid` BIGINT UNSIGNED NOT NULL,
    `total_paid` DECIMAL(18, 4) NULL,
    `product_base_price` DECIMAL(18, 4) NULL,
    `contract_length_type_name` VARCHAR(20) NULL,
    `contract_length` DECIMAL(18, 4) NULL,
    `fulfilment_count` DECIMAL(18, 4) NOT NULL,
    `report_ivwcategory` VARCHAR(20) NULL,
    `ivwcategory_cf` VARCHAR(20) NULL,
    `ivwcategory_berechnet` VARCHAR(20) NULL,
    `art` ENUM('Print', 'ePaper') NOT NULL,
    `lieferdatum` DATE NOT NULL,
    PRIMARY KEY (`subscriptionid`, `lieferdatum`, `art`)
) ENGINE=InnoDB
"""

_STAGING_COLUMNS = [
    "schedule",
    "subscriptionid",
    "orderid",
    "total_paid",
    "product_base_price",
    "contract_length_type_name",
    "contract_length",
    "fulfilment_count",
    "report_ivwcategory",
    "ivwcategory_cf",
    "ivwcategory_berechnet",
    "art",
    "lieferdatum",
]
_ALIASES = {
    "schedule": "schedule",
    "schedule_mon-sun": "schedule",
    "schedule_mon-su": "schedule",
    "subscriptionid": "subscriptionid",
    "orderid": "orderid",
    "totalpaid": "total_paid",
    "productbaseprice": "product_base_price",
    "contractlengthtypename": "contract_length_type_name",
    "contractlength": "contract_length",
    "fulfilmentcount": "fulfilment_count",
    "circulationcount": "fulfilment_count",
    "ivwcategory": "report_ivwcategory",
    "ivw_parametervalue": "ivwcategory_cf",
    "ivw_calculation": "ivwcategory_berechnet",
    "periodstart": "lieferdatum",
}
_REPORT_FILE_PATTERN = re.compile(
    r"^IVWReportAschendorff(?P<entitlements>Entitlements)?-"
    r"(?P<timestamp>\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2})-.+\.csv$"
)


@dataclass(frozen=True)
class IvwImportSummary:
    """Fasst einen IVW-Sammelimport zusammen."""

    file_count: int
    row_count: int


def _identifier(name: str) -> str:
    """Validiert einen SQL-Bezeichner."""
    if not re.fullmatch(r"[A-Za-z0-9_]+", name):
        raise ValueError(f"Ungueltiger SQL-Bezeichner: {name}")
    return f"`{name}`"


def read_ivw_report(csv_path: str | Path, art: ReportArt) -> pd.DataFrame:
    """Normalisiert einen IVW-Report und behaelt die bisherige Duplikatregel bei."""
    report = pd.read_csv(csv_path, dtype=str, keep_default_na=False)
    report = report.rename(
        columns={column: _ALIASES.get(column.strip().lower().replace(" ", ""), column) for column in report.columns}
    )
    required = {"subscriptionid", "orderid", "lieferdatum", "fulfilment_count"}
    missing = sorted(required.difference(report.columns))
    if missing:
        raise ValueError("IVW-Report enthaelt Pflichtspalten nicht: " + ", ".join(missing))
    for column in _STAGING_COLUMNS:
        if column not in report.columns:
            report[column] = pd.NA
    report["subscriptionid"] = report["subscriptionid"].str.strip()
    report["orderid"] = report["orderid"].str.strip()
    report["lieferdatum"] = pd.to_datetime(report["lieferdatum"], errors="coerce").dt.date
    for column in ("total_paid", "product_base_price", "contract_length", "fulfilment_count"):
        report[column] = pd.to_numeric(report[column], errors="coerce")
    report["contract_length"] = report["contract_length"].where(report["contract_length_type_name"].ne("Year"), 12)
    report["art"] = art
    report = report.dropna(subset=["subscriptionid", "orderid", "lieferdatum", "fulfilment_count"])
    report = report.loc[report["subscriptionid"].ne("") & report["orderid"].ne("")]
    return (
        report.sort_values("orderid")
        .drop_duplicates(subset=["subscriptionid", "lieferdatum", "art"], keep="last")[_STAGING_COLUMNS]
        .reset_index(drop=True)
    )


def _insert_staging_rows(cursor: Any, report: pd.DataFrame) -> None:
    """Schreibt die bereits bereinigten CSV-Zeilen in die temporaere Tabelle."""
    columns = ", ".join(_identifier(column) for column in _STAGING_COLUMNS)
    placeholders = ", ".join(f"%({column})s" for column in _STAGING_COLUMNS)
    update = ", ".join(
        f"{_identifier(column)} = VALUES({_identifier(column)})"
        for column in _STAGING_COLUMNS
        if column not in {"subscriptionid", "lieferdatum", "art"}
    )
    rows = [
        {key: None if pd.isna(value) else value for key, value in row.items()}
        for row in report.to_dict(orient="records")
    ]
    if rows:
        cursor.executemany(
            f"INSERT INTO `{STAGING_TABLE}` ({columns}) VALUES ({placeholders}) ON DUPLICATE KEY UPDATE {update}", rows
        )


def _enrich_and_upsert(cursor: Any, target_table: str) -> None:
    """Reichert Stagingdaten vollstaendig an und schreibt die SQLMesh-Grundlage."""
    target = _identifier(target_table)
    cursor.execute(f"""
        INSERT INTO {target} (
            schedule, subscriptionid, orderid, total_paid, product_base_price,
            contract_length_type_name, contract_length, fulfilment_count,
            report_ivwcategory, ivwcategory_cf, ivwcategory_berechnet, art,
            lieferdatum, ausgabedatum, pva, gesamt_pva, objekt, welt,
            ivwcategory, meldung, is_ivw_relevant, plz
        )
        SELECT
            src.schedule, src.subscriptionid, src.orderid, src.total_paid,
            src.product_base_price, src.contract_length_type_name, src.contract_length,
            src.fulfilment_count, src.report_ivwcategory, src.ivwcategory_cf,
            src.ivwcategory_berechnet, src.art, src.lieferdatum, cal.issue_date,
            pva.SAP, pva.Gesamt_SAP, pva.Objekt,
            vkorg.vkorg_bereich AS welt,
            category.IVWCategory, category.Meldung,
            CASE WHEN sub.ServiceTitle = 'Sonntags ePaper' THEN 0
                 WHEN category.Meldung IS NULL THEN 0
                 WHEN src.art = 'Print' AND category.Meldung = 'FREIST' THEN 0
                 ELSE 1 END,
            acc.HomePostCode
        FROM `{STAGING_TABLE}` AS src
        LEFT JOIN tb_subscriptionsreport_shortened AS sub
            ON sub.SubscriptionID = src.subscriptionid
        INNER JOIN tb_et_calendar AS cal
            ON cal.cal_date = src.lieferdatum AND cal.et_date = 1
        LEFT JOIN tb_accountreport_faktur AS acc
            ON acc.accountid = CASE
                WHEN sub.DeliveryInformationReference = 'leer'
                    OR sub.DeliveryInformationReference IS NULL THEN SUBSTR(sub.Payer, -9)
                ELSE SUBSTR(sub.DeliveryInformationReference, -9) END
        LEFT JOIN tb_mapping_pva AS pva
            ON pva.eSuite = CASE
                WHEN src.art = 'ePaper' AND sub.PVA IS NOT NULL AND LEFT(sub.PVA, 1) <> 'E'
                    THEN CONCAT('E', sub.PVA)
                WHEN src.art = 'Print' AND LEFT(sub.PVA, 1) IN ('E', 'D')
                    THEN SUBSTR(sub.PVA, 2)
                ELSE sub.PVA END
        LEFT JOIN tb_orderreport_faktur AS orders ON orders.OrderID = src.orderid
        LEFT JOIN tb_vouchers_esuite AS voucher ON voucher.VoucherCode = orders.ActivationCode
        LEFT JOIN tb_ivw_mapping_ivwcategory AS category
            ON category.IVWCategory_esuite = COALESCE(voucher.IVWCategory, sub.IVWCategory)
        LEFT JOIN tb_mapping_vkorg AS vkorg
            ON vkorg.vkorg_original = sub.VkOrg
        ON DUPLICATE KEY UPDATE
            schedule = VALUES(schedule), orderid = VALUES(orderid), total_paid = VALUES(total_paid),
            product_base_price = VALUES(product_base_price),
            contract_length_type_name = VALUES(contract_length_type_name),
            contract_length = VALUES(contract_length), fulfilment_count = VALUES(fulfilment_count),
            report_ivwcategory = VALUES(report_ivwcategory), ivwcategory_cf = VALUES(ivwcategory_cf),
            ivwcategory_berechnet = VALUES(ivwcategory_berechnet), ausgabedatum = VALUES(ausgabedatum),
            pva = VALUES(pva), gesamt_pva = VALUES(gesamt_pva), objekt = VALUES(objekt), welt = VALUES(welt),
            ivwcategory = VALUES(ivwcategory), meldung = VALUES(meldung),
            is_ivw_relevant = VALUES(is_ivw_relevant), plz = VALUES(plz)
    """)


def import_ivw_report_direct(
    csv_path: str | Path,
    art: ReportArt,
    target_table: str = TARGET_TABLE,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
    create_table: bool = True,
) -> int:
    """Importiert einen Report direkt als vollstaendige SQLMesh-Detailgrundlage."""
    report = read_ivw_report(csv_path, art)
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        connection.autocommit = False
        with connection.cursor() as cursor:
            if create_table:
                cursor.execute(CREATE_TARGET_SQL.format(table=_identifier(target_table).strip("`")))
            cursor.execute(CREATE_STAGING_SQL.format(table=STAGING_TABLE))
            _insert_staging_rows(cursor, report)
            _enrich_and_upsert(cursor, target_table)
        connection.commit()
        return len(report)
    except (mariadb.Error, ValueError, pd.errors.ParserError):
        connection.rollback()
        raise
    finally:
        connection.close()


def find_ivw_reports(directory: str | Path) -> list[tuple[Path, ReportArt]]:
    """Findet IVW-Reports eines Verzeichnisses in zeitlicher Reihenfolge.

    Dateien mit anderen Namen werden bewusst nicht beruecksichtigt. Damit kann ein
    Verzeichnis mit weiteren Arbeitsdateien sicher als Importquelle dienen.
    """
    source_directory = Path(directory)
    if not source_directory.is_dir():
        raise ValueError(f"IVW-Importverzeichnis existiert nicht: {source_directory}")

    reports: list[tuple[str, Path, ReportArt]] = []
    for csv_path in source_directory.iterdir():
        if not csv_path.is_file():
            continue
        match = _REPORT_FILE_PATTERN.fullmatch(csv_path.name)
        if match is None:
            continue
        art: ReportArt = "ePaper" if match.group("entitlements") else "Print"
        reports.append((match.group("timestamp"), csv_path, art))
    return [(csv_path, art) for _, csv_path, art in sorted(reports)]


def import_ivw_directory_direct(
    directory: str | Path,
    target_table: str = TARGET_TABLE,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
    create_table: bool = True,
) -> IvwImportSummary:
    """Importiert alle erkannten IVW-Reports eines Verzeichnisses.

    Der Sammelimport verschiebt oder loescht keine Quelldateien. Jeder Report wird
    einzeln committed; bei einem Fehler bleibt die fehlerhafte Datei unveraendert
    und der Import wird mit dem Fehler beendet.
    """
    reports = find_ivw_reports(directory)
    if not reports:
        raise ValueError(f"Keine IVW-Reports im Verzeichnis gefunden: {directory}")

    row_count = 0
    for csv_path, art in reports:
        row_count += import_ivw_report_direct(csv_path, art, target_table, database, db_credentials, create_table)
    return IvwImportSummary(file_count=len(reports), row_count=row_count)


def main() -> None:
    """Fuehrt einen manuellen IVW-Direktimport aus."""
    parser = argparse.ArgumentParser(description="Importiert IVW-Reports als SQLMesh-Detailgrundlage.")
    parser.add_argument("source_path", type=Path, help="CSV-Datei oder Verzeichnis mit IVW-Reports")
    parser.add_argument("--art", choices=("Print", "ePaper"))
    parser.add_argument("--table", default=TARGET_TABLE)
    parser.add_argument("--database", default=DATABASE)
    parser.add_argument("--no-create-table", action="store_true")
    args = parser.parse_args()
    if args.source_path.is_dir():
        if args.art is not None:
            parser.error("--art ist nur beim Import einer einzelnen CSV erlaubt.")
        result = import_ivw_directory_direct(
            args.source_path, args.table, args.database, create_table=not args.no_create_table
        )
        print(f"{result.row_count} IVW-Detailzeilen aus {result.file_count} Dateien importiert.")
        return
    if args.art is None:
        parser.error("--art ist beim Import einer einzelnen CSV erforderlich.")
    count = import_ivw_report_direct(
        args.source_path, args.art, args.table, args.database, create_table=not args.no_create_table
    )
    print(f"{count} IVW-Detailzeilen importiert.")


if __name__ == "__main__":
    main()
